// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && caller != address(c));
        vm.assume(newOwner != address(0) && newOwner != address(c));

        // Start by transferring ownership to newOwner (the contract starts with deployer as owner)
        // We need to act as the deployer (address(this) in setUp)
        vm.prank(c.owner());
        c.transferOwnership(newOwner);

        // Now try to accept ownership as caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // The bug makes owner() return address(0) always. 
        // In the reference, owner() should never be address(0) after acceptOwnership returns successfully.
        assertTrue(!success || c.owner() != address(0));
    }
}

